from pathlib import Path
import hashlib,subprocess,json,os
root=Path("/home/appontrack/public_html/saas/mobile")
src=Path("/home/appontrack/public_html/saas/mobile/campaigns_api.php")
assert os.getuid()==2379 and root.is_dir() and not root.is_symlink()
for f in ["common.php","pilot_workspace.php"]:
 assert (root/f).is_file(), "Missing server dependency: "+f
data="<?php
declare(strict_types=1);
require __DIR__.'/common.php';
require __DIR__.'/pilot_workspace.php';
mobile_require_device();
if($_SERVER['REQUEST_METHOD']==='GET') {
    $campaigns=pilot_read('campaigns');
    mobile_json(['ok'=>true,'campaigns'=>array_slice(array_reverse($campaigns),0,60)]);
}
if($_SERVER['REQUEST_METHOD']!=='POST')mobile_json(['ok'=>false,'error'=>'method_not_allowed'],405);
$raw=(string)file_get_contents('php://input');
if(strlen($raw)>12000)mobile_json(['ok'=>false,'error'=>'too_large'],413);
$data=json_decode($raw,true);
if(!is_array($data)||($data['confirmed']??false)!==true)mobile_json(['ok'=>false,'error'=>'confirmation_required'],422);
try {
    $item=pilot_campaign_create((string)($data['name']??''),(string)($data['starts']??''),(string)($data['ends']??''),(string)($data['scenario']??''));
    mobile_json(['ok'=>true,'campaign'=>$item,'dispatched'=>false]);
} catch (InvalidArgumentException $e) {
    mobile_json(['ok'=>false,'error'=>'invalid_campaign'],422);
} catch (Throwable $e) {
    mobile_json(['ok'=>false,'error'=>'campaign_store_error'],500);
}
".encode("utf-8")
assert len(data)<5000
if src.exists():
 assert not src.is_symlink()
 if src.read_bytes()!=data:raise RuntimeError("Existing campaign API differs; inspect before overwrite")
else:
 fd=os.open(str(src),os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
 with os.fdopen(fd,"wb") as out:out.write(data)
result=subprocess.run(["/usr/local/bin/php","-l",str(src)],capture_output=True,text=True,timeout=8)
print(json.dumps({"ok":result.returncode==0,"lint":result.stdout.strip()[:200],"sha256":hashlib.sha256(data).hexdigest(),"created":src.is_file()}))
if result.returncode:raise RuntimeError("PHP lint failed")
